-- ============================================================
-- KodaRE — Phase 10 schema: persist Property Status ("New Transaction" / "Active" / "At risk").
-- Run this once in your Supabase project's SQL Editor (Project → SQL Editor → New query).
-- Safe to re-run.
-- Additive only — one nullable column on properties. Existing rows get status = null, which
-- the app treats the same as "Active" (recomputed from open maintenance tickets as usual).
--
-- Why: Property Status used to be computed fresh every time the app loaded and was never
-- actually saved to the database — so a property sitting in "New Transaction" (formerly
-- "Onboarding") would silently flip back to "Active" the next time anyone reloaded the page.
-- This column lets "New Transaction" persist until the Acquisition/Lease checklist's Stage
-- reaches "Owned" or "Leased", at which point the app moves it to "Active" automatically
-- and saves that too.

alter table properties add column if not exists status text;

-- ============================================================
-- Source: schema_phase11.sql
-- ============================================================
-- KodaRE — Phase 11 schema: HOA/Condo type indicator for owned properties.
-- Run this once in your Supabase project's SQL Editor (Project → SQL Editor → New query).
-- Safe to re-run.
-- Additive only — one nullable column. Existing rows get hoa_type = null (shows as
-- "— select —" until someone picks HOA or Condo).
--
-- Why: HOA/Condo stays a Yes/No field (per Sonia's direction), but "Yes" alone doesn't say
-- whether it's an HOA or a Condo association — which matters for fees, contacts, and portal
-- info. This column stores that distinction. It only surfaces in the UI once HOA/Condo = Yes.

alter table properties add column if not exists hoa_type text;

-- ============================================================
-- Source: schema_phase12.sql
-- ============================================================
-- KodaRE — Phase 12 schema: Comments & User Notes for Properties.
-- Run this once in your Supabase project's SQL Editor (Project → SQL Editor → New query).
-- Safe to re-run.
-- Additive only — two nullable text columns. Existing rows get null (shows as blank).
--
-- Why: the property Details tab replaced House Manager / Operating Program with a
-- Comments field (visible to other users) and a User Notes field (private to the
-- entering user), matching the same Comments/User Notes pattern already used on
-- Vendors. These two columns store that data.

alter table properties add column if not exists comments text;
alter table properties add column if not exists user_notes text;

-- ============================================================
-- Source: schema_phase13.sql
-- ============================================================
-- KodaRE — Phase 13 schema: Trash bin / restore for Properties.
-- Run this once in your Supabase project's SQL Editor (Project → SQL Editor → New query).
-- Safe to re-run.
-- Additive only — one nullable timestamp column, same pattern already used for
-- vendors.deleted_at and maintenance_tickets.deleted_at (see schema_phase9.sql).
--
-- Why: Senior Admin can now delete a property from the prototype. Deleting soft-deletes
-- it (sets deleted_at) so it moves to the Trash view, where it can be restored or
-- permanently deleted — it does not disappear immediately. Maintenance tickets, leases,
-- certificates, etc. that reference the property are left as-is (same non-cascading
-- behavior as deleting a vendor); they'll just show "—" for the property name until/unless
-- the property is restored.

alter table properties add column if not exists deleted_at timestamptz;

-- ============================================================
-- Source: schema_phase14.sql
-- ============================================================
-- KodaRE — Phase 14 schema: Loan detail fields for Properties (Scope §4.4 Loan & Debt Tracking).
-- Run this once in your Supabase project's SQL Editor (Project → SQL Editor → New query).
-- Safe to re-run.
-- Additive only — new nullable columns. Existing rows get null (shows as blank/editable).
--
-- Why: the property Loan tab used to read from a static, hardcoded sample list that only
-- covered a handful of properties and wasn't editable or persisted anywhere. It now reads
-- and writes directly to the property record (same admin-editable pattern as the rest of
-- Overview/Details), so any owned property can have its loan info entered and saved.
-- loan_initial and loan_remaining already existed (principal/current balance); this adds
-- the remaining loan detail fields.

alter table properties add column if not exists loan_lender text;
alter table properties add column if not exists loan_contact text;
alter table properties add column if not exists loan_acct_no text;
alter table properties add column if not exists loan_orig_date text;
alter table properties add column if not exists loan_rate numeric(5,3);
alter table properties add column if not exists loan_rate_type text;
alter table properties add column if not exists loan_term_mo integer;
alter table properties add column if not exists loan_maturity text;
alter table properties add column if not exists loan_payment numeric(10,2);
alter table properties add column if not exists loan_escrow numeric(10,2);
alter table properties add column if not exists loan_lien text;
alter table properties add column if not exists loan_prepay text;

-- ============================================================
-- Source: schema_phase15.sql
-- ============================================================
-- KodaRE — Phase 15 schema: Real user roles (Scope §3.2 Permissions Matrix).
-- Run this once in your Supabase project's SQL Editor (Project → SQL Editor → New query).
-- Safe to re-run.
--
-- Why: Supabase's Authentication panel manages logins (email/password) but has no concept
-- of KodaRE's three roles (Senior Admin / Office Staff / Field Staff). Today the role switcher
-- in the app top bar is just a UI convenience — it isn't tied to who's actually signed in, and
-- anyone signed in could click it and get Senior Admin's view. This creates a real roles table
-- and locks the app down to read each signed-in user's actual assigned role.
--
-- How role assignment works day to day:
--   1. You still create the person's login the same way you do today — Supabase dashboard →
--      Authentication → Users → Add user (email + password).
--   2. The first time that person signs into KodaRE, the app automatically adds them to the
--      list below with the safe default role "office" (Office Staff).
--   3. You (Senior Admin) open KodaRE → User Management and change their role there. That's
--      the "R/W Senior Admin only" User Management capability from §3.2 — enforced below.
--
-- role values match the app's internal role keys: 'admin' (Senior Admin), 'office' (Office
-- Staff), 'caregiver' (Field Staff).

create table if not exists user_roles (
  user_id uuid primary key references auth.users(id) on delete cascade,
  email text not null,
  name text,
  role text not null default 'office' check (role in ('admin','office','caregiver')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index if not exists user_roles_email_idx on user_roles (lower(email));

-- Helper functions used by RLS policies here and in phase16. security definer so they can read
-- user_roles even from inside policies ON user_roles itself, without infinite recursion.
create or replace function public.current_user_role()
returns text
language sql
security definer
stable
set search_path = public
as $$
  select role from user_roles where user_id = auth.uid();
$$;

create or replace function public.current_role_is_admin()
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select coalesce((select role from user_roles where user_id = auth.uid()) = 'admin', false);
$$;

create or replace function public.current_role_is_admin_or_office()
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select coalesce((select role from user_roles where user_id = auth.uid()) in ('admin','office'), false);
$$;

alter table user_roles enable row level security;

drop policy if exists "user_roles_select_self_or_admin" on user_roles;
create policy "user_roles_select_self_or_admin" on user_roles
  for select using (auth.uid() = user_id or current_role_is_admin());

-- First-login self-registration: a signed-in user may create their OWN row, but only ever
-- with the safe default role 'office' — they cannot self-promote to admin or Field Staff.
drop policy if exists "user_roles_self_insert_office_only" on user_roles;
create policy "user_roles_self_insert_office_only" on user_roles
  for insert with check (auth.uid() = user_id and role = 'office');

drop policy if exists "user_roles_admin_insert_any" on user_roles;
create policy "user_roles_admin_insert_any" on user_roles
  for insert with check (current_role_is_admin());

drop policy if exists "user_roles_admin_update_any" on user_roles;
create policy "user_roles_admin_update_any" on user_roles
  for update using (current_role_is_admin());

drop policy if exists "user_roles_admin_delete_any" on user_roles;
create policy "user_roles_admin_delete_any" on user_roles
  for delete using (current_role_is_admin());

-- IMPORTANT — one-time manual step after running this migration:
-- This table starts empty, so there is no admin yet and the chicken-and-egg "only an admin can
-- promote someone to admin" rule would otherwise lock everyone out. Run this once, filling in
-- your own login email, to seed yourself as the first Senior Admin:
--
--   insert into user_roles (user_id, email, name, role)
--   select id, email, 'Sonia Sehra', 'admin' from auth.users where email = 'YOUR-LOGIN-EMAIL@example.com'
--   on conflict (user_id) do update set role = 'admin';
--
-- After that, everyone else can be managed from KodaRE's User Management screen (Senior Admin only).

-- ============================================================
-- Source: schema_phase16.sql
-- ============================================================
-- KodaRE — Phase 16 schema: Enforce the §3.2 Permissions Matrix at the database level.
-- Run this once in your Supabase project's SQL Editor, AFTER schema_phase15.sql.
-- Safe to re-run.
--
-- Why: phase15 gave the app a real user_roles table. This phase replaces the old blanket
-- "any signed-in user can do anything" policies with role-aware ones, so the permission rules
-- are enforced by the database itself — not just hidden buttons in the UI. Today, anyone signed
-- in could open the browser console and write directly to Supabase regardless of their role;
-- after this migration, the database rejects it.
--
-- What this does cover (table-level, matches §3.2 directly):
--   - Everyone signed in can still read (R) the operational tables.
--   - Only Office Staff and Senior Admin can create/edit records (W) — Field Staff
--     stay read-only, except they can still submit a new maintenance ticket (§3.2's "W/R*").
--   - Only Senior Admin can delete anything, or touch Reference Lists at all (§3.2: "Office
--     Staff and Field Staff have no access" to the Assumptions/Reference Lists area).
--
-- What this does NOT cover, and why (documented limitations, not oversights):
--   - §3.2 draws some lines WITHIN a single table (e.g., on Properties: Office Staff can R/W
--     basic info but only Read cost-basis/loan/valuation fields). Row-level security can't see
--     column-level distinctions, so those specific fields are protected by a trigger below
--     instead (a real, database-enforced rule — just a different mechanism than a policy).
--   - "Field Staff access is scoped to properties they're assigned to" needs a
--     property-to-field-staff assignment relationship, which doesn't exist yet as a feature (no
--     UI builds that assignment today). Until that's built, a Field Staff member's read access isn't
--     narrowed to only their properties. Flagging this so it isn't mistaken for an oversight —
--     worth a follow-up phase once "Property assignment to Field Staff" is a real feature.
--   - "Vendor visibility flagged for Field Staff" (approved vendors only) has the same gap —
--     no visibility-flag column exists on vendors yet.
--   - "Reports — financial/executive: Senior Admin only" is enforced today the way it always
--     has been (client-side, since reports are computed from the tables above, not their own
--     table) — this migration doesn't change that.

-- ================= Properties =================
drop policy if exists "authenticated_select_properties" on properties;
create policy "authenticated_select_properties" on properties for select using (auth.role() = 'authenticated');
drop policy if exists "authenticated_insert_properties" on properties;
drop policy if exists "office_admin_insert_properties" on properties;
create policy "office_admin_insert_properties" on properties for insert with check (current_role_is_admin_or_office());
drop policy if exists "authenticated_update_properties" on properties;
drop policy if exists "office_admin_update_properties" on properties;
create policy "office_admin_update_properties" on properties for update using (current_role_is_admin_or_office());
drop policy if exists "admin_delete_properties" on properties;
create policy "admin_delete_properties" on properties for delete using (current_role_is_admin());

-- Column-level backstop: cost basis, valuation, and loan fields are Office Staff read-only /
-- Senior Admin read-write (§3.2 "Property cost basis & purchase history" and "Loans & debt").
create or replace function public.enforce_property_financial_columns()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if current_role_is_admin() then
    return new;
  end if;
  if new.purchase_price is distinct from old.purchase_price
     or new.total_buyer_costs is distinct from old.total_buyer_costs
     or new.loan_initial is distinct from old.loan_initial
     or new.loan_remaining is distinct from old.loan_remaining
     or new.value is distinct from old.value
     or new.loan_lender is distinct from old.loan_lender
     or new.loan_contact is distinct from old.loan_contact
     or new.loan_acct_no is distinct from old.loan_acct_no
     or new.loan_orig_date is distinct from old.loan_orig_date
     or new.loan_rate is distinct from old.loan_rate
     or new.loan_rate_type is distinct from old.loan_rate_type
     or new.loan_term_mo is distinct from old.loan_term_mo
     or new.loan_maturity is distinct from old.loan_maturity
     or new.loan_payment is distinct from old.loan_payment
     or new.loan_escrow is distinct from old.loan_escrow
     or new.loan_lien is distinct from old.loan_lien
     or new.loan_prepay is distinct from old.loan_prepay
  then
    raise exception 'Only Senior Admin can change cost basis, valuation, or loan fields (Scope §3.2)';
  end if;
  return new;
end;
$$;

drop trigger if exists trg_enforce_property_financial_columns on properties;
create trigger trg_enforce_property_financial_columns
  before update on properties
  for each row execute function enforce_property_financial_columns();

