-- ============================================================
-- KodaRE — Phase 17 schema: real Documents storage, Team Notes, and the Life of Appliances
-- reference table — moves these three out of browser-only localStorage into Supabase.
-- Run this once in your Supabase project's SQL Editor, AFTER schema_phase16.sql.
-- Safe to re-run.

-- ================= Documents (Scope §4.1 Property Documents) =================
create table if not exists documents (
  id uuid primary key default gen_random_uuid(),
  property_id uuid not null references properties(id) on delete cascade,
  doc_type text not null,
  file_name text not null,
  file_path text not null,
  file_size integer,
  note text,
  uploaded_by text,
  created_at timestamptz not null default now()
);
create index if not exists idx_documents_property on documents(property_id);

alter table documents enable row level security;

drop policy if exists "authenticated_select_documents" on documents;
create policy "authenticated_select_documents" on documents for select using (auth.role() = 'authenticated');
drop policy if exists "office_admin_insert_documents" on documents;
create policy "office_admin_insert_documents" on documents for insert with check (current_role_is_admin_or_office());
drop policy if exists "office_admin_update_documents" on documents;
create policy "office_admin_update_documents" on documents for update using (current_role_is_admin_or_office());
drop policy if exists "admin_delete_documents" on documents;
create policy "admin_delete_documents" on documents for delete using (current_role_is_admin());

-- Storage bucket for property documents (deeds, leases, COs, inspection reports, photos).
insert into storage.buckets (id, name, public)
values ('documents', 'documents', false)
on conflict (id) do nothing;

drop policy if exists "office_admin_read_documents" on storage.objects;
create policy "office_admin_read_documents" on storage.objects for select
  using (bucket_id = 'documents' and current_role_is_admin_or_office());
drop policy if exists "office_admin_upload_documents" on storage.objects;
create policy "office_admin_upload_documents" on storage.objects for insert
  with check (bucket_id = 'documents' and current_role_is_admin_or_office());
drop policy if exists "office_admin_delete_documents_storage" on storage.objects;
create policy "office_admin_delete_documents_storage" on storage.objects for delete
  using (bucket_id = 'documents' and current_role_is_admin_or_office());

-- ================= Team Notes =================
create table if not exists team_notes (
  id uuid primary key default gen_random_uuid(),
  tag text not null default 'Note',
  pinned boolean not null default false,
  text text not null,
  created_by text,
  created_at timestamptz not null default now()
);

alter table team_notes enable row level security;

drop policy if exists "authenticated_select_team_notes" on team_notes;
create policy "authenticated_select_team_notes" on team_notes for select using (auth.role() = 'authenticated');
drop policy if exists "office_admin_insert_team_notes" on team_notes;
create policy "office_admin_insert_team_notes" on team_notes for insert with check (current_role_is_admin_or_office());
drop policy if exists "admin_delete_team_notes" on team_notes;
create policy "admin_delete_team_notes" on team_notes for delete using (current_role_is_admin());

-- ================= Life of Appliances reference table =================
-- Reuses the existing reference_lists table (same pattern already used for Service Category
-- and Service Type) — key 'LIFE_TABLE', data = {component: [avg_lifespan_years, replacement_cost]}.
-- Seeded here so the values match the app's hardcoded defaults; on conflict does nothing, so
-- this never overwrites edits you've already made in the Assumptions screen.
insert into reference_lists (key, data) values (
  'LIFE_TABLE',
  '{"HVAC":[25,10000],"Furnace":[20,6000],"Water heater":[15,2000],"Refrigerator":[10,1200],"Gas/electric range":[15,1200],"Oven":[15,1200],"Dishwasher":[10,800],"Microwave":[8,600],"Washing machine":[12,800],"Dryer":[12,800],"Carpeting":[10,0],"Roof":[25,11000]}'::jsonb
) on conflict (key) do nothing;

-- ============================================================
-- Source: schema_phase18.sql
-- ============================================================
-- KodaRE — Phase 18 schema: Field Staff property-scoping (Scope §3.2 asterisked rule:
-- "Field StaffCaregiver 'R' access is scoped to properties they are assigned to").
-- Run this once in your Supabase project's SQL Editor, AFTER schema_phase17.sql.
-- Safe to re-run.
--
-- What this does:
--   - Adds a real user_property_assignments join table (named per the scope doc's own data
--     model section) so a Field Staff person can be assigned one or more properties.
--   - Rewrites read (select) policies on Properties, Compliance (certificates/inspections),
--     and Maintenance tickets so a Field Staff login only sees rows for their assigned
--     properties. Office Staff and Senior Admin are unaffected — they still see everything,
--     per the matrix (only Field Staff's "R" is scoped).
--   - Adds a "posted" flag to Documents (Field Staff should not see unposted documents) and
--     an "approved" flag to Vendors (Field Staff should only see vendors flagged approved),
--     and scopes their read policies accordingly.
-- What this deliberately does NOT touch: Leases & Rent and the Purchase/Disposition/Licensing
-- checklists. The Permissions Matrix has no Field Staff row for these at all, so per your
-- direction they get zero access — their select policies stay "authenticated only" which in
-- practice means Office Staff/Senior Admin only, since the app's UI never shows those nav
-- items to Field Staff in the first place. (If a Field Staff account ever called the API
-- directly it would still see these today — closing that fully would mean adding the same
-- kind of role check here. Flagging as a known follow-up, not done in this migration.)

-- ================= Property assignments =================
create table if not exists user_property_assignments (
  user_id uuid not null references user_roles(user_id) on delete cascade,
  property_id uuid not null references properties(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, property_id)
);
create index if not exists idx_upa_property on user_property_assignments(property_id);

alter table user_property_assignments enable row level security;

-- A person can see their own assignments; Office Staff/Senior Admin can see everyone's
-- (matches matrix: "Property assignment to caregivers" = Office Staff R, Senior Admin R/W).
drop policy if exists "select_own_or_office_admin_assignments" on user_property_assignments;
create policy "select_own_or_office_admin_assignments" on user_property_assignments
  for select using (user_id = auth.uid() or current_role_is_admin_or_office());
-- Only Senior Admin can actually make/remove an assignment.
drop policy if exists "admin_insert_assignments" on user_property_assignments;
create policy "admin_insert_assignments" on user_property_assignments
  for insert with check (current_role_is_admin());
drop policy if exists "admin_delete_assignments" on user_property_assignments;
create policy "admin_delete_assignments" on user_property_assignments
  for delete using (current_role_is_admin());

-- Helper: is the signed-in user assigned to this specific property? (No admin/office bypass
-- baked in here on purpose — callers combine this with current_role_is_admin_or_office()
-- explicitly, so each policy below stays readable about who it's actually scoping.)
create or replace function public.current_user_assigned_to_property(pid uuid)
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select exists(
    select 1 from user_property_assignments where user_id = auth.uid() and property_id = pid
  );
$$;

-- ================= Properties — Field Staff scoped read =================
drop policy if exists "authenticated_select_properties" on properties;
create policy "authenticated_select_properties" on properties for select using (
  current_role_is_admin_or_office() or current_user_assigned_to_property(id)
);

-- ================= Compliance: certificates & inspections =================
drop policy if exists "authenticated_select_certificates" on certificates;
create policy "authenticated_select_certificates" on certificates for select using (
  current_role_is_admin_or_office() or current_user_assigned_to_property(property_id)
);
drop policy if exists "authenticated_select_inspections" on inspections;
create policy "authenticated_select_inspections" on inspections for select using (
  current_role_is_admin_or_office() or current_user_assigned_to_property(property_id)
);

-- ================= Maintenance tickets =================
-- Field Staff can still submit (insert) a ticket for any property per the existing phase16
-- policy — this only scopes what they can READ back afterward to their assigned properties.
drop policy if exists "authenticated_select_tickets" on maintenance_tickets;
create policy "authenticated_select_tickets" on maintenance_tickets for select using (
  current_role_is_admin_or_office() or current_user_assigned_to_property(property_id)
);

-- ================= Documents — add "posted" flag =================
-- Field Staff should not see unposted (draft) documents at all, even for their own property.
alter table documents add column if not exists posted boolean not null default false;

drop policy if exists "authenticated_select_documents" on documents;
create policy "authenticated_select_documents" on documents for select using (
  current_role_is_admin_or_office()
  or (posted and current_user_assigned_to_property(property_id))
);

-- ================= Vendors — add "approved" flag + geography scoping =================
-- Field Staff should only see vendors flagged approved AND that serve the metro area of at
-- least one property they're assigned to. Existing office_admin_* insert/update/delete
-- policies from phase16 already let Office Staff/Senior Admin set this flag — no new write
-- policy needed.
alter table vendors add column if not exists approved boolean not null default false;

drop policy if exists "authenticated_select_vendors" on vendors;
create policy "authenticated_select_vendors" on vendors for select using (
  current_role_is_admin_or_office()
  or (
    approved and exists (
      select 1 from user_property_assignments upa
      join properties p on p.id = upa.property_id
      where upa.user_id = auth.uid()
        and p.metro is not null
        and (vendors.metro ? p.metro)
    )
  )
);

-- ============================================================
-- Source: schema_phase19.sql
-- ============================================================
-- KodaRE — Phase 19 schema: real photo/file attachments on Maintenance Tickets.
-- Replaces the fake "Add a photo" toggle in the mobile Field Staff flow (which only ever set
-- a boolean/counter on the ticket — no real file was ever captured, uploaded, or stored) with
-- a genuine attachment table + Storage bucket, separate from the existing "invoices" bucket
-- (vendor invoices) and "documents" bucket (per-property deeds/leases/etc.) — this one is
-- per-ticket, for photos of the issue and any other file a Field Staff or Office Staff person
-- wants to attach directly to a maintenance ticket.
-- Run this once in your Supabase project's SQL Editor, AFTER schema_phase18.sql.
-- Safe to re-run.

-- ================= Ticket attachments =================
create table if not exists ticket_attachments (
  id uuid primary key default gen_random_uuid(),
  ticket_id uuid not null references maintenance_tickets(id) on delete cascade,
  kind text not null default 'photo' check (kind in ('photo','file')),
  file_name text not null,
  file_path text not null,
  file_size integer,
  uploaded_by text,
  created_at timestamptz not null default now()
);
create index if not exists idx_ticket_attachments_ticket on ticket_attachments(ticket_id);

alter table ticket_attachments enable row level security;

-- Helper: which property does this ticket belong to? Used below so Field Staff can be scoped
-- to attachments on tickets for properties they're assigned to (same rule as the tickets
-- themselves, from Phase 18) without duplicating that join everywhere.
create or replace function public.ticket_property(tid uuid)
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select property_id from maintenance_tickets where id = tid;
$$;

drop policy if exists "select_ticket_attachments" on ticket_attachments;
create policy "select_ticket_attachments" on ticket_attachments for select using (
  current_role_is_admin_or_office() or current_user_assigned_to_property(public.ticket_property(ticket_id))
);
-- Field Staff can attach their own photos/files (e.g. from the mobile report flow or when
-- adding a completed-work photo later); Office/Admin can attach for any ticket.
drop policy if exists "insert_ticket_attachments" on ticket_attachments;
create policy "insert_ticket_attachments" on ticket_attachments for insert with check (
  current_role_is_admin_or_office() or current_user_assigned_to_property(public.ticket_property(ticket_id))
);
-- Deleting an attachment (mistake, wrong photo, etc.) is Office/Admin only — matches the
-- pattern used for Documents and Team Notes.
drop policy if exists "delete_ticket_attachments" on ticket_attachments;
create policy "delete_ticket_attachments" on ticket_attachments for delete using (
  current_role_is_admin_or_office()
);

-- ================= Storage bucket =================
-- Path convention: {ticket_id}/{timestamp}_{filename} — the policies below parse the ticket_id
-- back out of the path via storage.foldername() to apply the same property-scoping as the
-- table rows above.
insert into storage.buckets (id, name, public)
values ('ticket_attachments', 'ticket_attachments', false)
on conflict (id) do nothing;

drop policy if exists "select_ticket_attachments_storage" on storage.objects;
create policy "select_ticket_attachments_storage" on storage.objects for select using (
  bucket_id = 'ticket_attachments' and (
    current_role_is_admin_or_office()
    or current_user_assigned_to_property(public.ticket_property(((storage.foldername(name))[1])::uuid))
  )
);
drop policy if exists "insert_ticket_attachments_storage" on storage.objects;
create policy "insert_ticket_attachments_storage" on storage.objects for insert with check (
  bucket_id = 'ticket_attachments' and (
    current_role_is_admin_or_office()
    or current_user_assigned_to_property(public.ticket_property(((storage.foldername(name))[1])::uuid))
  )
);
drop policy if exists "delete_ticket_attachments_storage" on storage.objects;
create policy "delete_ticket_attachments_storage" on storage.objects for delete using (
  bucket_id = 'ticket_attachments' and current_role_is_admin_or_office()
);

-- ============================================================
-- Source: schema_phase20.sql
-- ============================================================
-- KodaRE — Phase 20 schema:
-- 1) Field Staff photos/uploads and reported tickets now record the real signed-in person's
--    name (fixes a bug: the app was hardcoding every Field Staff account to "Alex Rivera" —
--    a leftover demo placeholder — so every real Field Staff person's tickets were attributed
--    to the same fake name, and "My reports" was showing everyone's tickets mixed together
--    instead of just their own). This is a client-side (index.html) fix, but this file adds
--    the one supporting piece that needs the database: a helper to look up the real signed-in
--    user's name for the policies below.
-- 2) Field Staff can now edit their OWN ticket's description and delete their OWN uploaded
--    photos/files, but ONLY while the ticket is still "Open" (nobody's picked it up yet).
--    Once a vendor is assigned or work starts, the original report locks — Office Staff and
--    the vendor are now relying on what was reported, so no more edits after that point.
--    Adding NEW photos/files stays allowed at any status (that's appending evidence over time,
--    like a photo of the completed work — not rewriting the original report).
-- Run this once in your Supabase project's SQL Editor, AFTER schema_phase19.sql. Safe to re-run.

-- ================= Helper: current signed-in user's display name =================
create or replace function public.current_user_display_name()
returns text
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(name, email) from user_roles where user_id = auth.uid();
$$;

-- ================= Maintenance tickets — Field Staff can edit their own, while Open =================
-- This is an ADDITIONAL policy alongside the existing office_admin_update_tickets policy
-- (Postgres OR's multiple permissive policies together) — Office Staff/Senior Admin keep full
-- update rights as before; this just adds a narrow allowance for the reporter.
-- Note: this guarantees the ticket stays "Open" before and after the edit, which is what
-- actually protects against edits after dispatch — but it doesn't lock individual columns
-- (cost/vendor) at the database level. The app's UI never exposes those fields to Field Staff
-- (only a description-edit box), so real-world risk is low; a column-level trigger is a
-- possible future hardening step if this app is ever opened to a raw API integration.
drop policy if exists "field_staff_update_own_open_tickets" on maintenance_tickets;
create policy "field_staff_update_own_open_tickets" on maintenance_tickets for update using (
  status = 'Open' and reporter = public.current_user_display_name()
) with check (
  status = 'Open' and reporter = public.current_user_display_name()
);

-- ================= Ticket attachments — Field Staff can delete their own, while Open =================
drop policy if exists "delete_ticket_attachments" on ticket_attachments;
create policy "delete_ticket_attachments" on ticket_attachments for delete using (
  current_role_is_admin_or_office()
  or exists (
    select 1 from maintenance_tickets mt
    where mt.id = ticket_attachments.ticket_id
      and mt.status = 'Open'
      and mt.reporter = public.current_user_display_name()
  )
);
drop policy if exists "delete_ticket_attachments_storage" on storage.objects;
create policy "delete_ticket_attachments_storage" on storage.objects for delete using (
  bucket_id = 'ticket_attachments' and (
    current_role_is_admin_or_office()
    or exists (
      select 1 from maintenance_tickets mt
      where mt.id = ((storage.foldername(name))[1])::uuid
        and mt.status = 'Open'
        and mt.reporter = public.current_user_display_name()
    )
  )
);

-- ================= Optional cleanup =================
-- If any real Field Staff person already submitted reports before this fix, those rows are
-- saved with reporter = 'Alex Rivera' and won't show up in that person's "My reports" list
-- going forward (since it now matches on their real name). If you want to reassign them,
-- find the real name to use in user_roles first, then run something like:
--   update maintenance_tickets set reporter = 'Their Real Name' where reporter = 'Alex Rivera';
-- Not run automatically — you know who actually reported each one, I don't.

-- ============================================================
-- Source: schema_phase21.sql
-- ============================================================
-- KodaRE — Phase 21 schema:
-- 1) Field Staff should NEVER see property-level Documents (deeds, leases, insurance
--    certificates, inspection reports, loan/mortgage paperwork) — confirmed with Sonia
--    Aug 4, 2026. Phase 18 had already hidden UNPOSTED documents from Field Staff, but still
--    let them see (the row/metadata for) POSTED documents at their assigned properties. This
--    removes that carve-out entirely: Documents are Office Staff / Senior Admin only, full
--    stop. Field Staff only ever deal with photos/files attached directly to a maintenance
--    ticket (proof of damage for repair) — that's the separate ticket_attachments feature from
--    Phase 19/20, which is unaffected by this change.
-- 2) Property records (all fields, every tab — Details, Acquisition, Disposition, Loan, etc.)
--    are edit-locked to Senior Admin at the database level, matching what the app's UI has
--    already enforced for a while (Office Staff sees every property field as read-only via
--    propTxt()). Office Staff could previously still have edited any property field, including
--    Loan & debt, by calling the API directly, bypassing the UI-only restriction — this closes
--    that gap so it's enforced by the database too, not just the interface.
-- Run this once in your Supabase project's SQL Editor, AFTER schema_phase20.sql. Safe to re-run.

-- ================= Documents — Field Staff: zero access, full stop =================
drop policy if exists "authenticated_select_documents" on documents;
create policy "authenticated_select_documents" on documents for select using (
  current_role_is_admin_or_office()
);

-- ================= Properties — Senior Admin only can edit (any field) =================
drop policy if exists "office_admin_update_properties" on properties;
create policy "admin_update_properties" on properties for update using (
  current_role_is_admin()
);

-- ============================================================
-- Source: schema_phase24.sql
-- ============================================================
-- KodaRE — Phase 24 schema:
-- Office Staff can now see which Field Staff are assigned to which property (Scope §3.2
-- matrix: "Property assignment to caregivers" = Office Staff R, Senior Admin R/W — the write
-- side was already Senior Admin only via Phase 18; this adds the read side for Office Staff).
--
-- Office Staff cannot read user_roles directly (Phase 15's "self_or_admin" policy is
-- unchanged and stays that way — Office Staff still can't browse the full user/role roster,
-- see Senior Admin accounts, or see anyone's role). Instead, this adds a narrow, security-
-- definer function that returns ONLY the name/email of Field Staff (role = 'caregiver')
-- who are assigned to a property, for callers who are Office Staff or Senior Admin. It
-- can't be used to see Office/Admin accounts or anyone's role — just "which Field Staff
-- covers this property," which is exactly what the matrix asks for.
-- Run this once in your Supabase project's SQL Editor, AFTER schema_phase21.sql. Safe to re-run.

create or replace function public.property_assignment_roster()
returns table(property_id uuid, user_id uuid, name text, email text)
language sql
stable
security definer
set search_path = public
as $$
  select upa.property_id, upa.user_id, ur.name, ur.email
  from user_property_assignments upa
  join user_roles ur on ur.user_id = upa.user_id
  where ur.role = 'caregiver'
    and current_role_is_admin_or_office();
$$;

grant execute on function public.property_assignment_roster() to authenticated;

-- ============================================================
-- Source: schema_phase28.sql
-- ============================================================
-- KodaRE — Phase 28 schema: lightweight error log (adapted from reshab-platform's error_log
-- pattern, scaled down for KodaRE's single-file/no-server-actions architecture).
--
-- reshab writes errors via server-side code running with a service-role key, which bypasses
-- RLS entirely. KodaRE has no equivalent server-side layer for this — every write comes
-- straight from the browser using the signed-in person's own session — so this table needs an
-- INSERT policy that any authenticated user can use (Field Staff included: an error they hit
-- is exactly the kind least likely to get reported to you directly). Reading and resolving
-- stays Senior Admin only, since message text can include property/vendor/ticket details.
--
-- Every " failed: " toast anywhere in the app (save/delete/restore/upload failures — the
-- existing convention almost every error.message already goes through) is now written here
-- automatically by toast()/logError() in index.html. Nothing needs to change per-feature.
--
-- Run this once in your Supabase project's SQL Editor. Safe to re-run.

create table if not exists public.error_log (
  id          uuid primary key default gen_random_uuid(),
  at          timestamptz not null default now(),
  message     text not null,
  path        text,               -- which screen it happened on, e.g. 'tickets', 'vendors'
  user_id     uuid references auth.users(id) on delete set null,
  user_email  text,
  user_role   text,
  resolved_at timestamptz,
  resolved_by uuid references auth.users(id) on delete set null
);

comment on table public.error_log is
  'Background failures, auto-logged from every " failed: " toast in index.html. Senior Admin read/resolve only. See Phase 28.';

create index if not exists error_log_recent_idx on public.error_log (at desc);
create index if not exists error_log_open_idx on public.error_log (at desc) where resolved_at is null;

alter table public.error_log enable row level security;

drop policy if exists "authenticated insert error log" on public.error_log;
create policy "authenticated insert error log" on public.error_log
  for insert
  with check (auth.role() = 'authenticated');

drop policy if exists "senior admin read error log" on public.error_log;
create policy "senior admin read error log" on public.error_log
  for select using (current_role_is_admin());

drop policy if exists "senior admin resolve error log" on public.error_log;
create policy "senior admin resolve error log" on public.error_log
  for update using (current_role_is_admin())
  with check (current_role_is_admin());

grant select, insert, update on public.error_log to authenticated;

-- ============================================================
-- Source: schema_phase29.sql
-- ============================================================
-- KodaRE — Phase 29 schema: scoped audit log (Scope §5.2/§5.5 "Audit log of all sensitive
-- data changes").
--
-- Deliberately scoped, not exhaustive — matches the spec's own language ("sensitive data
-- changes"), not reshab-platform's broader implementation which logs nearly every write in the
-- app. Covers: edits to Senior-Admin-locked property/loan fields, Senior Admin role changes,
-- property-caregiver assignment changes ("themselves auditable events" per §5.2), and
-- permanent deletions (as opposed to soft-delete/trash, which is already tracked separately).
--
-- No IP column. The spec asks for "from what IP," but even reshab-platform's own
-- implementation — despite running server-side code that could read it from request headers —
-- never actually wires that up in practice. KodaRE writes straight from the browser with no
-- server hop at all, so there's no trustworthy way to capture a client's IP here; a client
-- could just send whatever it wants. Skipped rather than faked.
--
-- Immutable by design: insert-only policy, no update or delete policy granted to anyone
-- (matches "immutable history" in §5.5) — not even Senior Admin can edit or remove an entry
-- through the app.
--
-- Run this once in your Supabase project's SQL Editor. Safe to re-run.

create table if not exists public.audit_log (
  id          uuid primary key default gen_random_uuid(),
  at          timestamptz not null default now(),
  actor_email text,
  actor_role  text,
  action      text not null,       -- e.g. 'Updated property field', 'Changed role', 'Assigned property', 'Permanently deleted'
  object_type text not null,       -- 'property' | 'user_role' | 'property_assignment' | 'vendor' | 'ticket'
  object_ref  text,                -- human-readable label: property name, user email, vendor name, ticket ref
  field       text,                -- which field changed, if applicable (e.g. 'purchasePrice')
  old_value   text,
  new_value   text
);

comment on table public.audit_log is
  'Immutable trail of sensitive changes: locked property/loan fields, role changes, property assignments, permanent deletions. Senior Admin read only. See Phase 29.';

create index if not exists audit_log_recent_idx on public.audit_log (at desc);

alter table public.audit_log enable row level security;

drop policy if exists "authenticated insert audit log" on public.audit_log;
create policy "authenticated insert audit log" on public.audit_log
  for insert
  with check (auth.role() = 'authenticated');

drop policy if exists "senior admin read audit log" on public.audit_log;
create policy "senior admin read audit log" on public.audit_log
  for select using (current_role_is_admin());

-- No update or delete policy — nobody can modify or remove an entry through the app, by design.

grant select, insert on public.audit_log to authenticated;

-- ============================================================
-- Source: schema_phase32.sql
-- ============================================================
-- KodaRE — Phase 32 schema: close the Field Staff RLS gap on Leases & Rent and the
-- Purchase/Disposition/Licensing checklists (Scope §3.2 Permissions Matrix).
--
-- The matrix lists no Field Staff row at all for these four areas, so per Sonia's direction
-- they get zero Field Staff access. The app's UI already enforces this — Field Staff's mobile
-- nav has no Leases, Acquisition, Disposition, or Licensing screen — but the database itself
-- was left open: every SELECT policy on these four tables was "authenticated_select_*" using
-- (auth.role() = 'authenticated'), which allows ANY signed-in user, including Field Staff. A
-- Field Staff account calling the Supabase API directly (bypassing the app's UI entirely)
-- could still read all of it. This was called out as a known follow-up in schema_phase18.sql
-- ("closing that fully would mean adding the same kind of role check here").
--
-- What this does: tightens the SELECT policy on all four tables to Office Staff / Senior Admin
-- only, matching the insert/update/delete policies these tables already had (those were never
-- open to Field Staff in the first place — only read access had the gap).
--
-- Run this once in your Supabase project's SQL Editor. Safe to re-run.

-- ================= Leases & Rent =================
drop policy if exists "authenticated_select_leases" on leases;
create policy "office_admin_select_leases" on leases for select using (
  current_role_is_admin_or_office()
);

-- ================= Purchase (Acquisition) Checklist =================
drop policy if exists "authenticated_select_purchase_checklists" on purchase_checklists;
create policy "office_admin_select_purchase_checklists" on purchase_checklists for select using (
  current_role_is_admin_or_office()
);

-- ================= Disposition Checklist =================
drop policy if exists "authenticated_select_disposition_checklists" on disposition_checklists;
create policy "office_admin_select_disposition_checklists" on disposition_checklists for select using (
  current_role_is_admin_or_office()
