-- ============================================================
-- Source: schema_phase33.sql
-- ============================================================
-- Phase 33 — verified ticket creator, separate from the editable "Reporter" name.
--
-- Why this exists: the "Reporter" field on a maintenance ticket was, until this phase, an
-- editable free-text field that defaulted to a hardcoded name ("Sonia S.") in the desktop
-- Add Ticket form regardless of who was actually signed in. That's fixed on the app side
-- (index.html now reads the signed-in user through one function, currentUserDisplayName(),
-- and the Reporter field is read-only). This migration adds the piece that can't be fixed
-- in the app alone: a column that records the *actual authenticated identity* of whoever
-- created the ticket, captured automatically at insert time, that Reporter can be checked
-- against later. Reporter stays human-editable (someone logging a ticket on a resident's
-- behalf may legitimately want it to say someone else's name) — created_by_email is not
-- editable anywhere in the app and is the more trustworthy of the two for any compliance
-- question about who actually used the system.
--
-- Existing tickets (everything created before this column existed) will have
-- created_by_email = null. There is no way to reconstruct that after the fact — nothing in
-- the schema up to this point recorded which authenticated user created a given row, so a
-- ticket's true creator for historical rows can only come from someone's own memory of who
-- logged it, not from the database. See the review query at the bottom of this file.

alter table maintenance_tickets add column if not exists created_by_email text;

comment on column maintenance_tickets.created_by_email is
  'Email of the authenticated user who created this ticket, captured automatically from the session at insert time. Null for tickets created before Phase 33 (Aug 2026) or Reporter cannot be relied on for verification. Not editable from the UI -- use this, not Reporter, when attribution needs to be verifiable.';

-- ---------------------------------------------------------------------------------------
-- Review query -- run this yourself in the Supabase SQL editor to see which existing
-- tickets have no verified creator on file (i.e. every ticket created before this phase).
-- This does NOT tell you who actually created each one -- it only tells you which rows are
-- relying solely on the free-text Reporter field, so you know which ones to sanity-check
-- against your own memory of who logged them, particularly any attributed to "Sonia S."
-- that you don't recall entering yourself.
-- ---------------------------------------------------------------------------------------
-- select id, ticket_no, reporter, title, created_at
-- from maintenance_tickets
-- where created_by_email is null
-- order by created_at desc;

-- Narrower version -- just the ones that say "Sonia S." specifically, oldest first so you
-- can cross-check against when multi-user access actually started:
-- select id, ticket_no, reporter, title, created_at
-- from maintenance_tickets
-- where reporter = 'Sonia S.' and created_by_email is null
-- order by created_at asc;

-- ============================================================
-- Source: schema_phase34.sql
-- ============================================================
-- KodaRE — Phase 34 schema: let a signed-in user actually save their own name.
-- Run this once in your Supabase project's SQL Editor, AFTER schema_phase15.sql. Safe to re-run.
--
-- Bug this fixes: the "What should we call you?" prompt (added in the app) kept reappearing on
-- every sign-in/refresh, and the greeting kept showing an email address instead of a name, for
-- anyone who isn't Senior Admin. Root cause: schema_phase15.sql gave user_roles a SELECT policy
-- for your own row, an INSERT policy for your own row (self-registration on first login), and
-- an UPDATE policy — but that UPDATE policy is "current_role_is_admin()" only. There has never
-- been a policy letting a person update their OWN row. Every Office Staff/Field Staff person's
-- attempt to save their own name via `update user_roles set name = ... where user_id = ...` has
-- always matched zero rows under Row Level Security. Supabase/PostgREST does not treat "RLS
-- silently matched nothing" as an error, so the app had no way to know the write did nothing —
-- it looked exactly like a successful save from the client's point of view, which is why this
-- was hard to catch just by watching the UI. (The app-side fix adds a .select() to that update
-- and checks the returned row count, so a future policy regression like this will surface a real
-- error message instead of failing silently again — but the actual bug is the missing policy
-- below.)
--
-- This adds a narrow self-update policy scoped to id = auth.uid(), plus a trigger that keeps it
-- narrow: a non-admin can change their own name (and the new name_prompt_dismissed flag below),
-- but NOT their own role or email through this path — role changes still require Senior Admin
-- via User Management, exactly as before. Without that trigger, a simple "you can update your
-- own row" policy would also let anyone promote themselves to Senior Admin, which is not the
-- intent here.

-- Tracks whether this person clicked "Skip for now" on the name prompt, so declining it once
-- doesn't mean being asked again on every future sign-in (same nagging problem, different form).
-- A Senior Admin can still set a name for someone from User Management at any time — see the
-- app-side change alongside this migration.
alter table user_roles add column if not exists name_prompt_dismissed boolean not null default false;

drop policy if exists "user_roles_self_update_own_row" on user_roles;
create policy "user_roles_self_update_own_row" on user_roles
  for update using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

create or replace function public.enforce_user_roles_self_update_columns()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if current_role_is_admin() then
    return new;
  end if;
  if new.role is distinct from old.role
     or new.email is distinct from old.email
     or new.user_id is distinct from old.user_id
  then
    raise exception 'You can only update your own name — role and email changes require Senior Admin (User Management)';
  end if;
  return new;
end;
$$;

drop trigger if exists trg_enforce_user_roles_self_update on user_roles;
create trigger trg_enforce_user_roles_self_update
  before update on user_roles
  for each row execute function enforce_user_roles_self_update_columns();

-- ============================================================
-- Source: schema_phase35.sql
-- ============================================================
-- KodaRE — Phase 35 schema: make maintenance_tickets.description mandatory.
--
-- DO NOT RUN THIS YET. Four existing rows (MT-1027, MT-1029, MT-1030, MT-1031) currently have
-- a blank description — this constraint will reject the migration outright while any row is
-- blank. Fix those four first (Maintenance → open the ticket → Description is editable for
-- Senior Admin), then re-run the check below. Once it returns zero rows, run the ALTER TABLE
-- statement beneath it.
--
-- Why this is needed: the app-side form already required a description on desktop and in
-- bulk upload, but the mobile "Report an issue" flow's Describe step never actually enforced
-- it — its Continue button was wired to always be enabled regardless of what was typed. On
-- top of that, attaching a photo while on that step triggered a re-render that rebuilt the
-- description textarea from stale state, silently discarding anything already typed. Both are
-- fixed in index.html now (the Continue button is gated on non-empty text, and the re-render
-- captures the live textarea value first) — this constraint is the backstop so no future route
-- into this table, present or not yet written, can leave description blank.

-- Run this first — confirms the table is actually clean before the constraint goes on:
--   select id, ticket_no, title, description, created_at from maintenance_tickets
--   where description is null or trim(description) = '' order by created_at desc;

alter table maintenance_tickets
  add constraint maintenance_tickets_description_required
  check (description is not null and trim(description) <> '');

-- If you'd rather backfill the four existing rows with a placeholder instead of retyping the
-- real text (which can't be recovered — it was lost before it ever reached the database, not
-- stored anywhere to restore from), this does that. Only the four rows already confirmed
-- blank are touched. Run BEFORE the ALTER TABLE above, not after.
--   update maintenance_tickets
--   set description = 'No description on file — lost to a bug in the mobile report flow, fixed Aug 10, 2026.'
--   where id in (
--     'e587e7a6-8fa1-402f-ad83-e8f17fd4afe4', -- MT-1031
--     '2bb0038d-84a1-43be-9338-9b4ca457b58c', -- MT-1030
--     '947cb4a6-4bb3-4ada-86ca-d7221d560d77', -- MT-1029
--     'd81d0e63-af3b-4dd4-9a8e-851b77ba2766'  -- MT-1027
--   );

-- ============================================================
-- Source: schema_phase36.sql
-- ============================================================
-- KodaRE — Phase 36 schema: private per-user Notes on Maintenance tickets.
-- Run once in your Supabase project's SQL Editor, AFTER schema_phase20.sql (uses the
-- current_role_is_admin() helper added there). Safe to re-run.
--
-- What this is: the ticket drawer's existing "Notes" field is one shared value everyone can
-- see and edit — that field is being relabeled "Comments" in the app (no data migration
-- needed, same column). This adds a second, genuinely separate concept: a private note per
-- ticket per person. Each person only ever sees and edits their own row; Senior Admin can see
-- everyone's for oversight, but — unlike Comments — can't edit anyone else's note but their own.

create table if not exists ticket_user_notes (
  id uuid primary key default gen_random_uuid(),
  ticket_id uuid not null references maintenance_tickets(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  note text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
unique(ticket_id, user_id)
);

alter table ticket_user_notes enable row level security;

drop policy if exists "ticket_user_notes_select" on ticket_user_notes;
create policy "ticket_user_notes_select" on ticket_user_notes for select using (
  user_id = auth.uid() or current_role_is_admin()
);

-- Insert/update/delete are intentionally NOT opened up to current_role_is_admin() — admin
-- oversight in the app is read-only by design (see Phase 33 description). Only the row's own
-- author can ever write to it.
drop policy if exists "ticket_user_notes_insert_own" on ticket_user_notes;
create policy "ticket_user_notes_insert_own" on ticket_user_notes for insert with check (
  user_id = auth.uid()
);

drop policy if exists "ticket_user_notes_update_own" on ticket_user_notes;
create policy "ticket_user_notes_update_own" on ticket_user_notes for update using (
  user_id = auth.uid()
) with check (
  user_id = auth.uid()
);

drop policy if exists "ticket_user_notes_delete_own" on ticket_user_notes;
create policy "ticket_user_notes_delete_own" on ticket_user_notes for delete using (
  user_id = auth.uid()
);

create or replace function public.touch_ticket_user_notes_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists trg_touch_ticket_user_notes on ticket_user_notes;
create trigger trg_touch_ticket_user_notes before update on ticket_user_notes
for each row execute function touch_ticket_user_notes_updated_at();

-- ============================================================
-- Source: schema_phase37.sql
-- ============================================================
-- KodaRE — Phase 37 schema: drop the payment_status check constraint on maintenance_tickets.
-- Run this once in your Supabase project's SQL Editor (Project → SQL Editor → New query).
-- Safe to re-run.
--
-- Why: Payment Status was just wired up as a live Reference List (Assumptions > Reference
-- Lists > Payment Status) — Senior Admin can now add/remove/reorder its values from the app
-- itself, same as Metro, Vendor Work Quality, Property Stage, etc. already work. Those columns
-- were deliberately never given a database-level check constraint, for exactly this reason: a
-- fixed constraint has no way to know about a value an admin adds later through the UI, so it
-- keeps rejecting saves the app itself is happy to allow. payment_status still had one left
-- over from Phase 1 (schema.sql), written before Reference Lists existed — which is why saving
-- a ticket with a newly-added Payment Status value fails with:
--   Save failed: new row for relation "maintenance_tickets" violates check constraint
--   "maintenance_tickets_payment_status_check"
-- This drops that constraint so Payment Status behaves like every other live Reference List —
-- any value validation now happens in the app (via the Reference List itself), not in Postgres.

alter table maintenance_tickets drop constraint if exists maintenance_tickets_payment_status_check;

-- ============================================================
-- Source: schema_phase38.sql
-- ============================================================
-- KodaRE — Phase 38 schema: target completion date on Maintenance tickets.
-- Run this once in your Supabase project's SQL Editor (Project → SQL Editor → New query).
-- Safe to re-run.
--
-- Adds a user-entered "target completion" date to maintenance_tickets, separate from the
-- app's auto-computed "actual completion" date (which is derived from the ticket's activity
-- log once it reaches Completed/Closed, and is never directly editable). Target completion is
-- the date staff expect/plan for the work to be done by, set from the ticket drawer or the
-- "New ticket" form.

alter table maintenance_tickets
  add column if not exists target_completion_date date;

comment on column maintenance_tickets.target_completion_date is
  'User-entered expected/target completion date. Distinct from actual completion, which is
   derived automatically from the activity log and not stored as its own column.';

